import type { Metadata } from "next";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";

// Brand typeface (Nexion), loaded once site-wide and self-hosted by next/font (no CDN at
// runtime). Exposed as CSS variables that globals.css maps onto Tailwind's
// --font-sans / --font-mono, so every page + the dashboard share one typeface
// instead of the browser default. Geist Sans + Geist Mono — one matched family
// for both UI text and data/code, replacing the previous Plus Jakarta Sans /
// JetBrains Mono pairing (see components/customer/PaymentStep.tsx, which used
// to load its own separate copy of Geist just to match Stripe's card fields —
// now redundant, since the whole page is Geist).
const nxSans = Geist({ subsets: ["latin"], variable: "--font-nx-sans", display: "swap" });
const nxMono = Geist_Mono({ subsets: ["latin"], variable: "--font-nx-mono", display: "swap" });
import { Analytics } from "@/components/marketing/Analytics";
import { TrackingProvider } from "@/components/marketing/TrackingProvider";
import MetaPixelTracker from "@/components/marketing/MetaPixelTracker";
import { OrganizationJsonLd } from "@/components/marketing/StructuredData";
import CookieConsent from "@/components/marketing/CookieConsent";
import LiveChat from "@/components/marketing/LiveChat";
import ChatWidget from "@/components/ChatWidget";
import { SandboxBanner } from "@/components/SandboxBanner";
import { SANDBOX } from "@/lib/sandbox";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";
const DESCRIPTION =
  "High-performance NVMe VPS hosting with instant deployment — control panels, game servers, VPNs, and domains. Deploy a server in seconds with full root access and a dedicated IP option.";

/**
 * Root metadata. A function, not a constant, because the platform name comes from
 * Settings → General (`brand_name`) — every string below used to hardcode "Nxeon", so
 * renaming the platform in the admin panel changed the browser tab, the per-page title
 * template, the Open Graph site name and the author/creator/publisher meta tags on exactly
 * nothing. Next.js only awaits a DB read here if the export is `generateMetadata`.
 *
 * Still hardcoded and out of scope for this pass: the schema.org JSON-LD in
 * components/marketing/StructuredData.tsx (Organization, Product, BlogPosting).
 *
 * Failure of the settings read is non-fatal on purpose and mirrors the `livechat_snippet`
 * read below: if Postgres is unreachable, the correct outcome is a page that renders with
 * the default title, not a 500 on the root layout that takes the whole site (including
 * /status) down with it.
 */
export async function generateMetadata(): Promise<Metadata> {
  // Only used when @/lib/settings cannot even be loaded. Kept a local literal rather
  // than a static SETTINGS_DEFAULTS import so the root layout still has no top-level
  // dependency on Prisma — the same reason the livechat read below is a dynamic import.
  let brand = "Nxeon";
  let fbDomainVerify = "";
  try {
    const { getSetting, SETTINGS_DEFAULTS } = await import("@/lib/settings");
    brand = (await getSetting("brand_name")).trim() || SETTINGS_DEFAULTS.brand_name;
    fbDomainVerify = (await getSetting("meta_domain_verification")).trim();
  } catch {
    /* settings unavailable — fall back to the built-in brand name */
  }
  return {
    metadataBase: new URL(APP_URL),
    // Meta Business domain verification — emits <meta name="facebook-domain-verification">
    // only when an operator has set the token in admin → Marketing → Tracking.
    ...(fbDomainVerify
      ? { verification: { other: { "facebook-domain-verification": fbDomainVerify } } }
      : {}),
    title: {
      default: `${brand} — Cloud VPS Hosting, Game Servers & Domains`,
      template: `%s — ${brand}`,
    },
    description: DESCRIPTION,
    applicationName: brand,
    keywords: [
      "VPS hosting",
      "cloud VPS",
      "game server hosting",
      "Minecraft server hosting",
      "NVMe VPS",
      "affordable VPS",
      "domain registration",
      "dedicated IP",
      "Singapore VPS",
      "cPanel hosting",

import type { NodeProvider } from "@prisma/client";

/**
 * Valid datacenter-code per provider, plus a human-readable label for each.
 * `Node.region` is a plain string (not an enum) because datacenter codes
 * grow far more often than providers do — same "fast-changing categorical
 * value, validated in code not the DB" convention this schema already uses
 * for StaffGrant.area (see lib/staff-grants.ts). Validate any new/edited
 * Node's region against `NODE_REGIONS[provider]` rather than trusting a
 * free-typed string from the admin form.
 *
 * Codes are each provider's OWN real datacenter code (OVH's/Hetzner's own
 * naming), not a platform-invented scheme — "sgp1" (OVH Singapore, where the
 * primary node actually is — confirmed via geoip-lite against its live
 * public IP, not guessed) and "fsn1" (Hetzner Falkenstein, Germany, the new
 * node) are both real. The other codes below are real provider datacenter
 * codes too, listed so the region field has somewhere to grow without a
 * schema change — add more here as real nodes are added, not speculatively.
 */
export const NODE_REGIONS: Record<NodeProvider, string[]> = {
  OVH: ["sgp1", "bhs1", "gra1", "rbx1", "waw1"],
  HETZNER: ["fsn1", "nbg1", "hel1", "ash1", "hil1"],
};

export const REGION_LABELS: Record<string, string> = {
  sgp1: "Singapore",
  bhs1: "Beauharnois, CA",
  gra1: "Gravelines, FR",
  rbx1: "Roubaix, FR",
  waw1: "Warsaw, PL",
  fsn1: "Falkenstein, DE",
  nbg1: "Nuremberg, DE",
  hel1: "Helsinki, FI",
  ash1: "Ashburn, US",
  hil1: "Hillsboro, US",
};

/**
 * Customer-facing location labels — deliberately simpler than REGION_LABELS
 * above. A customer picking where their server lives doesn't need (and often
 * won't recognize) the exact datacenter city — "Falkenstein, DE" confused
 * customers who don't know it's the small German town OVH/Hetzner's
 * Falkenstein facility sits in. REGION_LABELS stays as-is for admin/ops
 * screens, where the precise city genuinely matters (e.g. telling apart two
 * German facilities, fsn1 vs nbg1, if both are ever in use at once).
 */
export const CUSTOMER_REGION_LABELS: Record<string, string> = {
  sgp1: "Singapore",
  bhs1: "Canada",
  gra1: "France",
  rbx1: "France",
  waw1: "Poland",
  fsn1: "Germany",
  nbg1: "Germany",
  hel1: "Finland",
  ash1: "United States",
  hil1: "United States",
};

export function customerRegionLabel(region: string): string {
  return CUSTOMER_REGION_LABELS[region] ?? REGION_LABELS[region] ?? region;
}

/** ISO2 country code per region, for a flag icon next to a location card (optional UI nicety). */
export const REGION_COUNTRY: Record<string, string> = {
  sgp1: "sg",
  bhs1: "ca",
  gra1: "fr",
  rbx1: "fr",
  waw1: "pl",
  fsn1: "de",
  nbg1: "de",
  hel1: "fi",
  ash1: "us",
  hil1: "us",
};

export function isValidRegion(provider: NodeProvider, region: string): boolean {
  return NODE_REGIONS[provider]?.includes(region) ?? false;
}
