input.content:
/* ===========================================================================
   Nxeon v5 — "Instrument".

   A measurement sheet, not a landing page. Near-black ground, a visible
   12-column grid, hairline rules, one signal colour, and real data laid out
   the way a spec sheet or a bench instrument lays it out.

   RULES THIS FILE HOLDS ITSELF TO
   - No photography, no illustration, no iconography. Type, rules, numbers.
   - Zero border-radius, zero box-shadow-as-depth, zero gradients used as
     decoration. The only gradients here DRAW RULES (the column grid and the
     ruler ticks) — they are structure, not shading.
   - Exactly one chromatic value (--sig), reserved for things you can interact
     with: focus, hover, the grid cursor, the selected control, the one filled
     button, and the "best value per unit" marker. Everything else is
     greyscale. If a colour appears anywhere that is not interactive or not a
     computed result, it is a bug.

   EVERYTHING is scoped under `.v5` so it cannot leak into the marketing site,
   the portal, or the three sibling concepts sharing this checkout. No bare
   element selectors, no :root overrides.
   =========================================================================== */

.v5 {
  /* ---- ground ----------------------------------------------------------- */
  --ink: #07080a; /* page ground — near-black, not black: 1px rules need somewhere to sit */
  --ink-rise: #0c0e11; /* raised block: table heads, control strips */
  --rule: #1a1d22; /* hairline — the workhorse */
  --rule-hi: #2a2f36; /* emphasised hairline: section tops, thead underline */

  /* ---- type ------------------------------------------------------------- */
  --fg: #edeff2; /* primary */
  --fg-mid: #949aa3; /* prose, secondary values */
  --fg-dim: #5c626b; /* micro-labels, column provenance */

  /* ---- the one signal colour -------------------------------------------- */
  --sig: #ffb020; /* amber. Interactive + computed only. */
  --sig-lift: #ffc44f; /* its hover state */
  --sig-ink: #0a0a0a; /* text on a signal fill */

  --pad: clamp(16px, 3.2vw, 44px);
  --measure: 1360px;

  background: var(--ink);
  color: var(--fg-mid);
  font-family: var(--font-v5-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  min-height: 100vh;
}

/* ---------------------------------------------------------------------------
   THE SHEET + THE VISIBLE GRID

   The brief asks for the column structure to SHOW. It is drawn, not implied:
   `.rules` paints a 1px line down the left edge of each of twelve columns,
   inset to the sheet's content box so the lines land exactly where the grid
   items land. It sits behind everything at low contrast and never intercepts
   a pointer.
   --------------------------------------------------------------------------- */
.v5 .sheet {
  position: relative;
  max-width: var(--measure);
  margin-inline: auto;
  padding-inline: var(--pad);
}

.v5 .rules {
  position: absolute;
  inset: 0 var(--pad);
  pointer-events: none;
  z-index: 0;
  background-image: linear-gradient(to right, var(--rule) 0 1px, transparent 1px);
  background-size: calc(100% / 12) 100%;
  background-repeat: repeat-x;
  opacity: 0.55;
}

/* Everything that is content sits above the rules layer. */
.v5 .sheet > *:not(.rules) {
  position: relative;
  z-index: 1;
}

@media (max-width: 860px) {
  /* Twelve 1px lines across a phone is noise, not structure. Four reads as a grid. */
  .v5 .rules {
    background-size: calc(100% / 4) 100%;
  }
}

/* 12-col grid. Spans are explicit classes rather than Tailwind utilities so
   nothing here can be out-specified by (or accidentally depend on) the shared
   utility layer the sibling concepts are also using. */
.v5 .g12 {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  column-gap: 0;
  align-content: start;
}
.v5 .s1 { grid-column: span 1; }
.v5 .s2 { grid-column: span 2; }
.v5 .s3 { grid-column: span 3; }
.v5 .s4 { grid-column: span 4; }
.v5 .s5 { grid-column: span 5; }
.v5 .s6 { grid-column: span 6; }
.v5 .s7 { grid-column: span 7; }
.v5 .s8 { grid-column: span 8; }
.v5 .s11 { grid-column: span 11; }
.v5 .s12 { grid-column: 1 / -1; }

@media (max-width: 1023px) {
  .v5 .g12 > [class*="s"] { grid-column: 1 / -1; }
}

/* Cell padding that keeps text off the drawn column rule. */
.v5 .pad-l { padding-left: 14px; }
.v5 .pad-r { padding-right: 14px; }

/* ---------------------------------------------------------------------------
   TYPE

   Martian Mono is the DISPLAY face — headline, every label, every number. It
   is a genuine monospace (Evil Martians' mono cut of Martian Grotesk), wide
   and mechanical, and at 300 weight it holds a hero line without shouting.
   Public Sans carries prose only: a plainly neutral Franklin derivative with
   real tabular figures, chosen because it has no voice of its own to argue
   with the mono. Neither is Inter, Geist or Space Grotesk.
   --------------------------------------------------------------------------- */
.v5 .mono {
  font-family: var(--font-v5-mono), ui-monospace, SFMono-Regular, monospace;
  font-variant-numeric: tabular-nums;
}

/* Micro-label: the 10px uppercase mono that names every field on the sheet. */
.v5 .lbl {
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 500;
  line-height: 1.3;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--fg-dim);
}

/* Provenance: the database column a figure came from. Deliberately the
   smallest type on the page — present for anyone who wants to check it,
   invisible to anyone who doesn't. */
.v5 .src {
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-size: 9.5px;
  line-height: 1.4;
  letter-spacing: 0.02em;
  color: var(--fg-dim);
  white-space: nowrap;
}

.v5 .display {
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-weight: 300;
  color: var(--fg);
  letter-spacing: -0.045em;
  line-height: 1.02;
}

.v5 h1.display {
  font-size: clamp(30px, 5.1vw, 66px);
  margin: 0;
}

.v5 h2.display {
  font-size: clamp(20px, 2.3vw, 31px);
  letter-spacing: -0.035em;
  margin: 0;
}

.v5 p {
  margin: 0;
  max-width: 62ch;
}

.v5 .num {
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-variant-numeric: tabular-nums;
  font-weight: 400;
  color: var(--fg);
}

/* ---------------------------------------------------------------------------
   RULES AND TICKS

   The ruler strip is a pure-CSS measurement scale: a 5px minor tick every 8px
   and a 10px major tick every 80px, both hanging off a hairline. It is the
   one piece of "ornament" on the page and it is literally a ruler.
   --------------------------------------------------------------------------- */
.v5 .hr {
  height: 0;
  border: 0;
  border-top: 1px solid var(--rule);
  margin: 0;
}
.v5 .hr-hi { border-top-color: var(--rule-hi); }

.v5 .ticks {
  height: 12px;
  border-bottom: 1px solid var(--rule-hi);
  background-image:
    linear-gradient(to right, var(--rule-hi) 0 1px, transparent 1px),
    linear-gradient(to right, var(--rule) 0 1px, transparent 1px);
  background-size: 80px 9px, 8px 4px;
  background-position: left bottom, left bottom;
  background-repeat: repeat-x, repeat-x;
}

/* ---------------------------------------------------------------------------
   MASTHEAD
   --------------------------------------------------------------------------- */
.v5 .strip {
  border-bottom: 1px solid var(--rule);
}

.v5 .strip-in {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 22px;
  align-items: center;
  padding-block: 7px;
}

.v5 .mast {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  align-items: center;
  justify-content: space-between;
  padding-block: 16px;
  border-bottom: 1px solid var(--rule-hi);
}

.v5 .brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  text-decoration: none;
  color: var(--fg);
}

/* The real NX mark, rendered monochrome. The asset is a blue→violet gradient
   PNG; on a sheet with exactly one chromatic value, dropping it in as-is would
   introduce two more. Desaturating is the same thing a printed product manual
   does to a logo — it is still the real mark, and no logo has been invented. */
.v5 .brand img {
  display: block;
  height: 20px;
  width: auto;
  filter: grayscale(1) brightness(1.75) contrast(0.95);
}

.v5 .brand b {
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-weight: 500;
  font-size: 13px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}

.v5 .nav {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 2px;
  align-items: center;
}

.v5 .nav a {
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--fg-mid);
  text-decoration: none;
  padding: 7px 10px;
  border: 1px solid transparent;
  transition: color 0.12s linear, border-color 0.12s linear;
}
.v5 .nav a:hover { color: var(--sig); border-color: var(--rule-hi); }

/* ---------------------------------------------------------------------------
   CONTROLS
   --------------------------------------------------------------------------- */
.v5 .btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--fg);
  background: transparent;
  border: 1px solid var(--rule-hi);
  padding: 13px 18px;
  cursor: pointer;
  text-decoration: none;
  transition: color 0.12s linear, border-color 0.12s linear, background-color 0.12s linear;
}
.v5 .btn:hover { color: var(--sig); border-color: var(--sig); }

.v5 .btn-sig {
  color: var(--sig-ink);
  background: var(--sig);
  border-color: var(--sig);
}
.v5 .btn-sig:hover { color: var(--sig-ink); background: var(--sig-lift); border-color: var(--sig-lift); }

/* Segmented switch — the basis and unit selectors on the comparator. */
.v5 .seg {
  display: inline-flex;
  border: 1px solid var(--rule-hi);
}

.v5 .seg button {
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--fg-dim);
  background: transparent;
  border: 0;
  border-right: 1px solid var(--rule-hi);
  padding: 9px 12px;
  cursor: pointer;
  transition: color 0.12s linear, background-color 0.12s linear;
}
.v5 .seg button:last-child { border-right: 0; }
.v5 .seg button:hover { color: var(--fg); }
.v5 .seg button[aria-pressed="true"] {
  color: var(--sig-ink);
  background: var(--sig);
}

.v5 .field {
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-size: 11px;
  letter-spacing: 0.04em;
  color: var(--fg);
  background: var(--ink-rise);
  border: 1px solid var(--rule-hi);
  padding: 9px 11px;
  width: 100%;
  max-width: 320px;
}
.v5 .field::placeholder { color: var(--fg-dim); letter-spacing: 0.1em; text-transform: uppercase; font-size: 9.5px; }
.v5 .field:focus { outline: none; border-color: var(--sig); }

.v5 a.lk {
  color: var(--fg);
  text-decoration: none;
  border-bottom: 1px solid var(--rule-hi);
  transition: color 0.12s linear, border-color 0.12s linear;
}
.v5 a.lk:hover { color: var(--sig); border-bottom-color: var(--sig); }

.v5 :focus-visible {
  outline: 2px solid var(--sig);
  outline-offset: 1px;
}

/* ---------------------------------------------------------------------------
   TABLES

   Real <table> markup with collapsed borders. Numeric columns are right
   aligned and tabular so digits stack into a column you can read down — the
   whole reason this concept uses tables where the sibling concepts use cards.
   --------------------------------------------------------------------------- */
.v5 .tbl {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.v5 .tbl th,
.v5 .tbl td {
  border-bottom: 1px solid var(--rule);
  padding: 8px 12px;
  text-align: left;
  vertical-align: baseline;
}

.v5 .tbl thead th {
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--fg-dim);
  border-bottom-color: var(--rule-hi);
  white-space: nowrap;
}

.v5 .tbl td.r,
.v5 .tbl th.r {
  text-align: right;
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-variant-numeric: tabular-nums;
}

.v5 .tbl tbody tr:hover { background: #101317; }
.v5 .tbl tbody td.k { color: var(--fg); }

.v5 .scroll-x {
  overflow-x: auto;
  overscroll-behavior-x: contain;
}

/* ---------------------------------------------------------------------------
   SECTION HEADERS — the numbered rule that opens every block.
   --------------------------------------------------------------------------- */
.v5 .shead {
  border-top: 1px solid var(--rule-hi);
  padding-top: 14px;
  padding-bottom: 20px;
  row-gap: 10px;
}

.v5 .shead .no {
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.1em;
  color: var(--sig);
}

.v5 .sect { padding-block: clamp(44px, 6vw, 88px); }

/* ---------------------------------------------------------------------------
   HERO
   --------------------------------------------------------------------------- */
.v5 .hero { padding-top: clamp(40px, 6vw, 84px); padding-bottom: clamp(36px, 5vw, 72px); row-gap: 42px; }

.v5 .hero-claims {
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  border: 1px solid var(--rule-hi);
  border-bottom: 0;
  margin-top: 30px;
}

.v5 .hero-claims > div {
  flex: 1 1 150px;
  border-bottom: 1px solid var(--rule-hi);
  border-right: 1px solid var(--rule-hi);
  padding: 12px 14px;
}
.v5 .hero-claims > div:last-child { border-right: 0; }

.v5 .hero-claims strong {
  display: block;
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-weight: 400;
  font-size: 17px;
  letter-spacing: -0.02em;
  color: var(--fg);
  margin-bottom: 3px;
}

.v5 .cta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 26px;
}

/* The hero readout — a spec block: field, value, source column. */
.v5 .readout {
  border: 1px solid var(--rule-hi);
  background: var(--ink-rise);
}

.v5 .readout-cap {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--rule-hi);
}

.v5 .readout .tbl th,
.v5 .readout .tbl td { padding: 7px 12px; }
.v5 .readout .tbl tr:last-child td { border-bottom: 0; }
.v5 .readout .tbl tbody tr:hover { background: #14171c; }

/* ---------------------------------------------------------------------------
   THE COMPARATOR GRID (§01)

   A role="grid" whose cursor is a 1px inset amber box — an oscilloscope
   cursor, not a hover state. The readout beneath it prints the cell's own
   arithmetic, which is the point: the number is checkable without leaving
   the page.
   --------------------------------------------------------------------------- */
.v5 .mx { outline: none; }

.v5 .mx .tbl td.cell {
  text-align: right;
  font-family: var(--font-v5-mono), ui-monospace, monospace;
  font-variant-numeric: tabular-nums;
  color: var(--fg);
  cursor: crosshair;
}

