/* ---------------------------------------------------------------------------
   MOTION

   There is almost none: 120ms linear colour transitions on interactive
   elements, and nothing animates on scroll. Nothing on this page is parked at
   opacity 0 waiting for an observer — the sheet is complete and readable the
   instant it paints, with JS disabled, which for this audience is the whole
   argument.
   --------------------------------------------------------------------------- */
@media (prefers-reduced-motion: reduce) {
  .v5 *,
  .v5 *::before,
  .v5 *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

@media (max-width: 640px) {
  .v5 .cat-cols { columns: 1; column-rule: 0; }
  .v5 .hero-claims > div { flex-basis: 100%; border-right: 0; }
}

import type { Metadata } from "next";
import { Martian_Mono, Public_Sans } from "next/font/google";
import "./v5.css";

/**
 * v5 shell — "Instrument".
 *
 * TWO faces, both loaded here, neither of them the site's own. The root layout
 * already ships Geist Sans/Mono as --font-nx-sans / --font-nx-mono; this
 * concept deliberately uses neither, because Geist (like Inter and Space
 * Grotesk) is the default a generated page arrives wearing, and the whole
 * premise here is a page that looks like engineers made it on purpose.
 *
 *  - Martian Mono is the DISPLAY face, not a code face used for data. It is
 *    Evil Martians' monospaced cut of Martian Grotesk — wide, squared,
 *    unmistakably mechanical — and it sets the headline, every micro-label and
 *    every number on the sheet. A mono at 300 weight and 66px is the single
 *    strongest signal this page sends.
 *  - Public Sans carries prose only. A plain Libre Franklin derivative with no
 *    voice of its own, which is exactly what should sit next to a mono that
 *    has plenty. Its tabular figures also mean a long text cell and a numeric
 *    cell in the same table still line up.
 *
 * Both are fixed-weight requests rather than variable: Martian Mono carries a
 * `wdth` axis as well as `wght`, and pinning the weights avoids shipping an
 * axis this page never varies.
 */
const v5Mono = Martian_Mono({
  subsets: ["latin"],
  weight: ["300", "400", "500"],
  variable: "--font-v5-mono",
  display: "swap",
});

const v5Sans = Public_Sans({
  subsets: ["latin"],
  weight: ["400", "500"],
  variable: "--font-v5-sans",
  display: "swap",
});

export const metadata: Metadata = {
  title: "Nxeon — instrument sheet",
  description:
    "Game servers, cloud VPS and web hosting across two regions. Every figure on this page is read from the production catalogue at request time.",
  // Bake-off concept, not a public page: keep it out of the index entirely.
  robots: { index: false, follow: false },
};

export default function V5Layout({ children }: { children: React.ReactNode }) {
  return <div className={`v5 ${v5Mono.variable} ${v5Sans.variable}`}>{children}</div>;
}

"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useCallback, useMemo, useRef, useState } from "react";

/**
 * §01 — the plan comparator.
 *
 * A measurement instrument rather than a pricing table. Columns are the live
 * `Plan` rows; rows are specs and the four unit prices DERIVED from them. A
 * cursor moves through the matrix with the arrow keys and the readout under
 * the grid prints the selected cell's own arithmetic — `3022 ÷ 8` — so the
 * number can be checked without leaving the page. That is the entire reason
 * this concept exists: an audience that distrusts marketing pages is handed
 * the working, not the conclusion.
 *
 * Nothing here is a literal. Every figure is a function of the `Plan` columns
 * the server handed down, which matters more than it sounds: `Plan.priceCents`
 * moved between two reads of the database while this page was being built, so
 * any number typed into the markup would already be wrong.
 */

export type MatrixPlan = {
  id: string;
  slug: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  /** Regular / renewal monthly price. The single source of truth. */
  priceCents: number;
  /** Resolved first-term monthly price, or null when the plan has no intro rate. */
  introCents: number | null;
};

type Basis = "first" | "renewal";

/** Cents in, "$12.34" out. No arithmetic beyond the divide. */
function usd(cents: number): string {
  return "$" + (cents / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

/** A unit rate in dollars. Sub-dollar rates get a third place or they all read "$0.00". */
function rate(dollars: number): string {
  return "$" + dollars.toLocaleString("en-US", {
    minimumFractionDigits: dollars < 1 ? 3 : 2,
    maximumFractionDigits: dollars < 1 ? 3 : 2,
  });
}

function trim(n: number): string {
  return Number.isInteger(n) ? String(n) : n.toFixed(1);
}

type RowDef = {
  key: string;
  label: string;
  source: string;
  /** Raw comparable magnitude for this plan at the chosen price basis. */
  get: (p: MatrixPlan, priceCents: number) => number;
  fmt: (v: number) => string;
  /** The working, shown in the readout. */
  expr: (p: MatrixPlan, priceCents: number) => string;
  /** Unit rows only: mark the lowest value in the row, and allow indexing. */
  unit: boolean;
};

const ROWS: RowDef[] = [
  {
    key: "cpu",
    label: "vCPU",
    source: "Plan.cpuCores",
    get: (p) => p.cpuCores,
    fmt: (v) => trim(v),
    expr: (p) => `Plan.cpuCores = ${p.cpuCores}`,
    unit: false,
  },
  {
    key: "ram",
    label: "Memory — GB",
    source: "Plan.ramMB",
    get: (p) => p.ramMB / 1024,
    fmt: (v) => trim(v),
    expr: (p) => `${p.ramMB} MB ÷ 1024`,
    unit: false,
  },
  {
    key: "disk",
    label: "NVMe — GB",
    source: "Plan.diskGB",
    get: (p) => p.diskGB,
    fmt: (v) => trim(v),
    expr: (p) => `Plan.diskGB = ${p.diskGB}`,
    unit: false,
  },
  {
    key: "bw",
    label: "Transfer — TB",
    source: "Plan.bandwidthTB",
    get: (p) => p.bandwidthTB,
    fmt: (v) => trim(v),
    expr: (p) => `Plan.bandwidthTB = ${p.bandwidthTB}`,
    unit: false,
  },
  {
    key: "price",
    label: "Price — per month",
    source: "Plan.priceCents",
    get: (_p, cents) => cents / 100,
    fmt: (v) => usd(Math.round(v * 100)),
    expr: (p, cents) =>
      cents === p.priceCents
        ? `Plan.priceCents = ${cents}¢`
        : `Plan.introPriceCents = ${cents}¢ (renews ${p.priceCents}¢)`,
    unit: false,
  },
  {
    key: "u-cpu",
    label: "$ per vCPU",
    source: "derived",
    get: (p, cents) => cents / 100 / p.cpuCores,
    fmt: (v) => rate(v),
    expr: (p, cents) => `${cents}¢ ÷ ${p.cpuCores} vCPU`,
    unit: true,
  },
  {
    key: "u-ram",
    label: "$ per GB memory",
    source: "derived",
    get: (p, cents) => cents / 100 / (p.ramMB / 1024),
    fmt: (v) => rate(v),
    expr: (p, cents) => `${cents}¢ ÷ ${trim(p.ramMB / 1024)} GB`,
    unit: true,
  },
  {
    key: "u-disk",
    label: "$ per GB NVMe",
    source: "derived",
    get: (p, cents) => cents / 100 / p.diskGB,
    fmt: (v) => rate(v),
    expr: (p, cents) => `${cents}¢ ÷ ${p.diskGB} GB`,
    unit: true,
  },
  {
    key: "u-bw",
    label: "$ per TB transfer",
    source: "derived",
    get: (p, cents) => cents / 100 / p.bandwidthTB,
    fmt: (v) => rate(v),
    expr: (p, cents) => `${cents}¢ ÷ ${trim(p.bandwidthTB)} TB`,
    unit: true,
  },
];

const cellId = (r: number, c: number) => `v5-mx-${r}-${c}`;

export function PlanMatrix({ plans }: { plans: MatrixPlan[] }) {
  const router = useRouter();
  const tableRef = useRef<HTMLTableElement | null>(null);
  const [basis, setBasis] = useState<Basis>("first");
  const [indexed, setIndexed] = useState(false);
  const [cur, setCur] = useState<{ r: number; c: number }>({ r: 5, c: 0 });

  const anyIntro = plans.some((p) => p.introCents !== null);

  /** The price basis in force for a given plan, in cents. */
  const centsFor = useCallback(
    (p: MatrixPlan) => (basis === "first" ? (p.introCents ?? p.priceCents) : p.priceCents),
    [basis],
  );

  /** values[r][c], plus the row minimum for the unit rows. */
  const grid = useMemo(() => {
    return ROWS.map((row) => {
      const vals = plans.map((p) => row.get(p, centsFor(p)));
      const min = vals.length ? Math.min(...vals) : 0;
      return { row, vals, min };
    });
  }, [plans, centsFor]);

  const lastR = ROWS.length - 1;
  const lastC = plans.length - 1;

  const move = useCallback(
    (r: number, c: number) => {
      const next = {
        r: Math.max(0, Math.min(lastR, r)),
        c: Math.max(0, Math.min(lastC, c)),
      };
      setCur(next);
    },
    [lastR, lastC],
  );

  const onKeyDown = (e: React.KeyboardEvent<HTMLTableElement>) => {
    const { r, c } = cur;
    switch (e.key) {
      case "ArrowUp": move(r - 1, c); break;
      case "ArrowDown": move(r + 1, c); break;
      case "ArrowLeft": move(r, c - 1); break;
      case "ArrowRight": move(r, c + 1); break;
      case "Home": move(r, 0); break;
      case "End": move(r, lastC); break;
      case "PageUp": move(0, c); break;
      case "PageDown": move(lastR, c); break;
      case "b": case "B":
        setBasis((b) => (b === "first" ? "renewal" : "first"));
        break;
      case "i": case "I":
        setIndexed((v) => !v);
        break;
      case "Enter":
        router.push(`/dashboard/deploy?product=vps&plan=${encodeURIComponent(plans[c].id)}`);
        break;
      default:
        return; // not ours — let the browser have it
    }
    e.preventDefault();
  };

  const curRow = grid[cur.r];
  const curPlan = plans[cur.c];
  const curVal = curRow?.vals[cur.c] ?? 0;
  const curIndexed = curRow?.row.unit && indexed && curRow.min > 0;

  return (
    <div className="mx">
      <div className="mx-bar">
        <div style={{ display: "flex", flexWrap: "wrap", gap: 18, alignItems: "center" }}>
          <div>
            <div className="lbl" style={{ marginBottom: 6 }}>Price basis</div>
            <div className="seg" role="group" aria-label="Price basis">
              <button
                type="button"
                aria-pressed={basis === "first"}
                onClick={() => setBasis("first")}
                disabled={!anyIntro}
              >
                First term
              </button>
              <button type="button" aria-pressed={basis === "renewal"} onClick={() => setBasis("renewal")}>
                Renewal
              </button>
            </div>
          </div>
          <div>
            <div className="lbl" style={{ marginBottom: 6 }}>Unit rows</div>
            <div className="seg" role="group" aria-label="Unit row display">
              <button type="button" aria-pressed={!indexed} onClick={() => setIndexed(false)}>
                Absolute
              </button>
              <button type="button" aria-pressed={indexed} onClick={() => setIndexed(true)}>
                Indexed
              </button>
            </div>
          </div>
        </div>
        <p className="src" style={{ whiteSpace: "normal", maxWidth: "34ch" }}>
          Arrow keys move the cursor · 1–{plans.length} jump column · B basis · I index · Enter opens the plan
        </p>
      </div>

      <div className="scroll-x">
        <table
          className="tbl"
          ref={tableRef}
          role="grid"
          tabIndex={0}
          aria-label="Plan comparator"
          aria-activedescendant={cellId(cur.r, cur.c)}
          onKeyDown={onKeyDown}
        >
          <caption className="lbl" style={{ textAlign: "left", paddingBottom: 10 }}>
            {plans.length} active VPS plans · {basis === "first" ? "first-term monthly rate" : "renewal monthly rate"}
            {indexed ? " · unit rows indexed to the best plan in each row" : ""}
          </caption>
          <thead>
            <tr role="row">
              <th role="columnheader" scope="col" style={{ minWidth: 168 }}>
                Measurement
              </th>
              {plans.map((p, c) => (
                <th
                  key={p.id}
                  role="columnheader"
                  scope="col"
                  className={`col-head${c === cur.c ? " in-col" : ""}`}
                  style={{ minWidth: 118 }}
                >
                  <em>{p.name}</em>
                  <span className="src">
                    {c + 1} · {p.slug}
                  </span>
                </th>
              ))}
              <th role="columnheader" scope="col" className="r" style={{ minWidth: 86 }}>
                Source
              </th>
            </tr>
          </thead>
          <tbody>
            {grid.map(({ row, vals, min }, r) => (
              <tr key={row.key} role="row" className={r === cur.r ? "in-row" : undefined}>
                <th role="rowheader" scope="row" className="k" style={{ fontWeight: 400, color: "var(--fg)" }}>
                  {row.label}
                </th>
                {vals.map((v, c) => {
                  const isBest = row.unit && vals.length > 1 && v === min;
                  const show = row.unit && indexed && min > 0 ? "×" + (v / min).toFixed(2) : row.fmt(v);
                  const isCur = r === cur.r && c === cur.c;
                  return (
                    <td
                      key={plans[c].id}
                      id={cellId(r, c)}
                      role="gridcell"
                      className={[
                        "cell",
                        row.unit ? "" : "dim",
                        isBest ? "best" : "",
                        isCur ? "cursor" : "",
                        c === cur.c ? "in-col" : "",
                      ].filter(Boolean).join(" ")}
                      aria-selected={isCur}
                      onMouseDown={() => {
                        move(r, c);
                        tableRef.current?.focus();
                      }}
                    >
                      {show}
                    </td>
                  );
                })}
                <td className="r src">{row.source}</td>
              </tr>
            ))}
            <tr role="row">
              <th role="rowheader" scope="row" className="lbl" style={{ paddingTop: 14 }}>
                Order
              </th>
              {plans.map((p, c) => (
                <td key={p.id} className={c === cur.c ? "in-col" : undefined} style={{ paddingTop: 14, textAlign: "right" }}>
                  <Link className="lk mono" style={{ fontSize: 10.5, letterSpacing: "0.12em" }} href={`/dashboard/deploy?product=vps&plan=${encodeURIComponent(p.id)}`}>
                    DEPLOY
                  </Link>
                </td>
              ))}
              <td />
            </tr>
          </tbody>
        </table>
      </div>

      {/* The cursor readout. An oscilloscope prints what the cursor sits on;
          so does this — including the division that produced it. */}
      <div className="mx-out" aria-live="polite">
        <span className="lbl">Cursor</span>
        <span className="mono" style={{ fontSize: 11 }}>
          {curPlan?.slug} / {curRow?.row.label}
        </span>
        <span className="v">
          {curIndexed && curRow ? "×" + (curVal / curRow.min).toFixed(2) : curRow?.row.fmt(curVal)}
        </span>
        <span className="expr">
          {curIndexed && curRow
            ? `${curRow.row.fmt(curVal)} ÷ ${curRow.row.fmt(curRow.min)} (best in row)`
            : curPlan && curRow
              ? curRow.row.expr(curPlan, centsFor(curPlan))
              : ""}
        </span>
      </div>

      {anyIntro ? (
        <p className="note" style={{ paddingTop: 12 }}>
          First-term rates come from <span className="mono">Plan.introPriceCents</span> and apply to the first term
          only; every plan then renews at <span className="mono">Plan.priceCents</span>, which is what the “Renewal”
          basis shows. Both bases are read from the same row, so neither can drift from what the card is charged.
        </p>
      ) : null}
    </div>
  );
}

"use client";

import Link from "next/link";
import { useMemo, useRef, useState } from "react";

/**
 * §02 — the game catalogue, as an index rather than a wall of key art.
 *
 * One row per game family that has live `GamePlan` tiers. Every column is an
 * aggregate over those tiers (how many tiers, the memory range they span, the
 * largest slot count, the cheapest first-term and renewal rate), so the table
 * says what a family actually costs and how far it scales instead of showing a
 * poster and a single "from" price.
 *
 * Sortable by any numeric column and filterable by name or genre, which is the
 * useful thing to be able to do with forty-odd rows — and the reason this
 * concept puts a table here where the sibling concepts put a carousel.
 */

export type GameRow = {
  family: string;
  name: string;
  href: string | null;
  genres: string[];
  tiers: number;
  ramMinMB: number;
  ramMaxMB: number;
  cpuMax: number;
  diskMaxGB: number;
  slotsMax: number | null;
  /** Cheapest live tier, renewal basis. */
  fromCents: number;
  /** Cheapest live tier, first-term basis (equals fromCents when no intro rate). */
  fromFirstCents: number;
};

type SortKey = "name" | "tiers" | "ram" | "cpu" | "disk" | "slots" | "from";

function usd(cents: number): string {
  return "$" + (cents / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function gb(mb: number): string {
  const v = mb / 1024;
  return Number.isInteger(v) ? String(v) : v.toFixed(1);
}

const COLS: { key: SortKey; label: string; right: boolean; num: boolean }[] = [
  { key: "name", label: "Family", right: false, num: false },
  { key: "tiers", label: "Tiers", right: true, num: true },
  { key: "ram", label: "Memory GB", right: true, num: true },
  { key: "cpu", label: "vCPU max", right: true, num: true },
  { key: "disk", label: "Disk GB max", right: true, num: true },
  { key: "slots", label: "Slots max", right: true, num: true },
  { key: "from", label: "From / mo", right: true, num: true },
];

function magnitude(r: GameRow, key: SortKey): number | string {
  switch (key) {
    case "name": return r.name.toLowerCase();
    case "tiers": return r.tiers;
    case "ram": return r.ramMaxMB;
    case "cpu": return r.cpuMax;
    case "disk": return r.diskMaxGB;
    case "slots": return r.slotsMax ?? -1;
    case "from": return r.fromFirstCents;
  }
}

export function GameIndex({
  rows,
  familiesWithPlans,
}: {
  rows: GameRow[];
  /** Distinct families with an active GamePlan row, which may exceed rows.length. */
  familiesWithPlans: number;
}) {
  const [q, setQ] = useState("");
  const [genre, setGenre] = useState<string | null>(null);
  const [sort, setSort] = useState<{ key: SortKey; dir: 1 | -1 }>({ key: "from", dir: 1 });
  const inputRef = useRef<HTMLInputElement | null>(null);

  const genres = useMemo(() => {
    const seen = new Set<string>();
    for (const r of rows) for (const g of r.genres) seen.add(g);
    return [...seen].sort();
  }, [rows]);

  const view = useMemo(() => {
    const needle = q.trim().toLowerCase();
    const filtered = rows.filter((r) => {
      if (genre && !r.genres.includes(genre)) return false;
      if (!needle) return true;
      return (
        r.name.toLowerCase().includes(needle) ||
        r.family.includes(needle) ||
        r.genres.some((g) => g.toLowerCase().includes(needle))
      );
    });
    const { key, dir } = sort;
    return [...filtered].sort((a, b) => {
      const av = magnitude(a, key);
      const bv = magnitude(b, key);
      if (av === bv) return a.name.localeCompare(b.name);
      return (av < bv ? -1 : 1) * dir;
    });
  }, [rows, q, genre, sort]);

  return (
    <div
      onKeyDown={(e) => {
        // "/" focuses the filter, the way it does in every tool this audience
        // already has open. Ignored while typing into a field.
        if (e.key === "/" && e.target instanceof HTMLElement && e.target.tagName !== "INPUT") {
          e.preventDefault();
          inputRef.current?.focus();
        }
      }}
    >
      <div className="mx-bar">
        <div style={{ display: "flex", flexWrap: "wrap", gap: 14, alignItems: "flex-end" }}>
          <div>
            <label className="lbl" htmlFor="v5-gq" style={{ display: "block", marginBottom: 6 }}>
              Filter — press /
            </label>
            <input
              id="v5-gq"
              ref={inputRef}
              className="field"
              type="search"
              value={q}
              placeholder="name or genre"
              onChange={(e) => setQ(e.target.value)}
            />
          </div>
          <div>
            <div className="lbl" style={{ marginBottom: 6 }}>Genre</div>
            <div className="chips">
              <button type="button" className="chip" aria-pressed={genre === null} onClick={() => setGenre(null)}>
                All
              </button>
              {genres.map((g) => (
                <button
                  key={g}
                  type="button"
                  className="chip"
                  aria-pressed={genre === g}
                  onClick={() => setGenre(genre === g ? null : g)}
                >
                  {g}
                </button>
              ))}
            </div>
          </div>
        </div>
        <p className="src" style={{ whiteSpace: "normal" }}>
          {view.length} of {rows.length} listed · {familiesWithPlans} families have live plans
        </p>
      </div>

      <div className="scroll-x">
        <table className="tbl" aria-label="Game families with live plans">
          <thead>
            <tr>
              <th style={{ width: 34 }} className="r">#</th>
              {COLS.map((col) => {
                const on = sort.key === col.key;
                return (
                  <th key={col.key} className={col.right ? "r" : undefined} scope="col" aria-sort={on ? (sort.dir === 1 ? "ascending" : "descending") : "none"}>
                    <button
                      type="button"
                      className="sortbtn"
                      data-on={on ? "1" : "0"}
                      onClick={() =>
                        setSort((s) => (s.key === col.key ? { key: col.key, dir: s.dir === 1 ? -1 : 1 } : { key: col.key, dir: 1 }))
                      }
                    >
                      {col.label}
                      <i aria-hidden="true">{on ? (sort.dir === 1 ? "▲" : "▼") : "•"}</i>
                    </button>
                  </th>
                );
              })}
              <th className="r" scope="col">Renews at</th>
              <th style={{ width: 150 }} scope="col">Genre</th>
            </tr>
          </thead>
          <tbody>
            {view.map((r, i) => (
              <tr key={r.family}>
                <td className="r idx">{String(i + 1).padStart(2, "0")}</td>
                <td className="k">
                  {r.href ? (
                    <Link className="lk" href={r.href}>{r.name}</Link>
                  ) : (
                    r.name
                  )}
                </td>
                <td className="r">{r.tiers}</td>
                <td className="r">{gb(r.ramMinMB)}–{gb(r.ramMaxMB)}</td>
                <td className="r">{r.cpuMax}</td>
                <td className="r">{r.diskMaxGB}</td>
                <td className="r">{r.slotsMax ?? "—"}</td>
                <td className="r" style={{ color: "var(--fg)" }}>{usd(r.fromFirstCents)}</td>
                <td className="r" style={{ color: "var(--fg-dim)" }}>
                  {r.fromCents === r.fromFirstCents ? "same" : usd(r.fromCents)}
                </td>
                <td className="genre">{r.genres.join(" · ") || "—"}</td>
              </tr>
            ))}
            {view.length === 0 ? (
              <tr>
                <td colSpan={10} className="src" style={{ padding: "18px 12px" }}>
                  No family matches that filter.
                </td>
              </tr>
            ) : null}
          </tbody>
        </table>
      </div>
    </div>
  );
}

